#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ContextMode {
    Brief,
    FullChat,
}

impl ContextMode {
    fn from_label(value: Option<&str>) -> Self {
        match value
            .map(str::trim)
            .unwrap_or("brief")
            .to_ascii_lowercase()
            .as_str()
        {
            "full_chat" | "full chat" | "full-chat" => Self::FullChat,
            _ => Self::Brief,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Brief => "brief",
            Self::FullChat => "full_chat",
        }
    }
}

