    fn run_command_turn(
        conn: &Connection,
        conversation_id: &str,
        soul: &Soul,
        text: &str,
    ) -> TurnResult {
        let request_id = uuid_like_id();
        let turn_id = format!("turn_{request_id}");
        maybe_handle_chat_command_with_conn(
            None,
            conn,
            conversation_id.to_string(),
            soul.character_id.clone(),
            text.to_string(),
            &request_id,
            &turn_id,
            ContextMode::Brief,
            None,
        )
        .expect("command result")
        .expect("recognized command")
    }

